style.css:
@-moz-document domain("roblox.com") {
/* Apply the custom Dr. Stone background image */
    body, 
    .container-main, 
    .content, 
    #container-main,
    .gandalf-roblox-pc-container {
        background-image: url('https://images-api.com') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
    }

    /* Make Roblox containers semi-transparent so you can see your wallpaper */
    .section-content,
    .home-header,
    .profile-header,
    .avatar-card-container,
    .game-card-container,
    .places-list-container,
    .item-card-container,
    .mCSB_container,
    .scroller {
        background: rgba(25, 25, 25, 0.75) !important;
        border-radius: 8px !important;
    }

    /* Adjust the main background transparency overlay if needed */
    .background-dark {
        background-color: rgba(10, 10, 15, 0.4) !important;
    }
}
